/** Real pointer gestures and native review routes; UUID stores, no output or sensor admission. */
public final class NightDialInteractionTest {
    private final Instrumentation i=InstrumentationRegistry.getInstrumentation();private final Context c=i.getTargetContext();private final UiDevice d=UiDevice.getInstance(i);private final List<Activity> owned=new CopyOnWriteArrayList<>();
    private UiObject2 waitText(String label){UiObject2 found=d.wait(Until.findObject(By.text(label)),5000);assertNotNull(label,found);return found;}
    private void click(String label){waitText(label).click();d.waitForIdle();}
    private UiObject2 dial(){UiObject2 view=d.wait(Until.findObject(By.descStartsWith("Rest window from ")),5000);assertNotNull("Native dial",view);return view;}
    private void capture(String name)throws Exception{NightDialCapture.frame(i,c,d,name);}
    private Point point(UiObject2 dial,int minute){android.graphics.Rect r=dial.getVisibleBounds();double angle=Math.toRadians(minute/4d-90);float s=r.width()/360f;return new Point(r.left+Math.round((180+130*(float)Math.cos(angle))*s),r.top+Math.round((151+130*(float)Math.sin(angle))*s));}
    private void drag(int from,int to){UiObject2 dial=dial();Point[] path=new Point[13];for(int n=0;n<path.length;n++)path[n]=point(dial,from+(to-from)*n/(path.length-1));assertTrue("One actual curved pointer gesture",d.swipe(path,4));waitText("Adjust night");}
    private void pointer(long down,int action,Point point){MotionEvent event=MotionEvent.obtain(down,SystemClock.uptimeMillis(),action,point.x,point.y,0);event.setSource(InputDevice.SOURCE_TOUCHSCREEN);try{assertTrue(i.getUiAutomation().injectInputEvent(event,true));}finally{event.recycle();}}
    private void cancelledDrag()throws Exception{UiObject2 face=dial();Point from=point(face,420),to=point(face,480);long down=SystemClock.uptimeMillis();pointer(down,MotionEvent.ACTION_DOWN,from);try{for(int n=1;n<=8;n++)pointer(down,MotionEvent.ACTION_MOVE,point(face,420+60*n/8));capture("dial-under-finger");assertFalse("A review only opens on release",d.hasObject(By.text("Adjust night")));}finally{pointer(down,MotionEvent.ACTION_CANCEL,to);}assertFalse(d.hasObject(By.text("Adjust night")));}
    private <T extends Activity>T launch(Class<T> type,Intent intent)throws Exception{Instrumentation.ActivityMonitor monitor=i.addMonitor(type.getName(),null,false);try{c.startActivity(intent.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));Activity activity=monitor.waitForActivityWithTimeout(5000);assertNotNull(type.getName(),activity);return type.cast(activity);}finally{i.removeMonitor(monitor);}}
    private void recreate(Class<? extends Activity> type)throws Exception{Activity before=owned.stream().filter(a->type.isInstance(a)&&!a.isDestroyed()&&!a.isFinishing()).reduce((a,b)->b).orElseThrow();Instrumentation.ActivityMonitor monitor=i.addMonitor(type.getName(),null,false);try{i.runOnMainSync(before::recreate);assertNotNull(monitor.waitForActivityWithTimeout(5000));}finally{i.removeMonitor(monitor);}d.waitForIdle();}
    @Test public void independentDragReviewSaveCancelRecreationAndSilentSettleIn()throws Exception{
        assertEquals("true",InstrumentationRegistry.getArguments().getString("ciReview"));assertEquals("1",d.executeShellCommand("getprop ro.kernel.qemu").trim());assertFalse(AlarmService.active);assertFalse(TrackingService.running);assertNull(SleepSoundService.snapshot());
        String name="dial-input-"+UUID.randomUUID(),database=name+".db";SharedPreferences plan=c.getSharedPreferences(name,0),mix=c.getSharedPreferences(name+"-mix",0);assertTrue(plan.edit().putInt("bedtime",1350).putInt("wakeTime",420).putInt("goal",510).commit());SoundMix initialMix=new SoundMix();initialMix.primary="Rain";initialMix.primaryGain=60;initialMix.brownGain=25;SoundPreferences.save(mix,initialMix);Map<String,?> original=new HashMap<>(Prefs.of(c).getAll()),originalMix=new HashMap<>(mix.getAll());
        AlarmScheduling.Port alarmPort=AlarmScheduling.port;java.util.concurrent.atomic.AtomicInteger alarmSchedules=new java.util.concurrent.atomic.AtomicInteger();Records.Factory records=Records.factory;SleepPlans.Factory plans=SleepPlans.factory;SleepPlans.Reminder reminders=SleepPlans.reminders;SoundPreferences.Factory sounds=SoundPreferences.factory;TrackingService.StoreFactory stores=TrackingActivity.stores;TrackingActivity.Commands commands=TrackingActivity.commands;LongSupplier clock=TonightScreen.clock;TimeZone zone=TimeZone.getDefault();java.util.concurrent.atomic.AtomicInteger schedules=new java.util.concurrent.atomic.AtomicInteger();
        Application app=(Application)c.getApplicationContext();Application.ActivityLifecycleCallbacks life=new Application.ActivityLifecycleCallbacks(){public void onActivityCreated(Activity a,Bundle state){owned.add(a);}public void onActivityStarted(Activity a){}public void onActivityResumed(Activity a){}public void onActivityPaused(Activity a){}public void onActivityStopped(Activity a){}public void onActivitySaveInstanceState(Activity a,Bundle state){}public void onActivityDestroyed(Activity a){}};app.registerActivityLifecycleCallbacks(life);
        try{
            AlarmScheduling.port=new AlarmScheduling.Port(){public boolean allowed(Context context){return true;}public void schedule(Context context,Alarm alarm){alarmSchedules.incrementAndGet();}};Records.factory=ctx->new Store(ctx,database);SleepPlans.factory=ctx->plan;SleepPlans.reminders=ctx->schedules.incrementAndGet();SoundPreferences.factory=ctx->mix;TrackingActivity.stores=ctx->new Store(ctx,database);TrackingActivity.commands=new TrackingActivity.Commands(){public TrackingService.Snapshot snapshot(){return null;}public void start(TrackingActivity owner,Intent request){fail("No sensor admission allowed in this review");}public void command(TrackingActivity owner,Intent request){fail("No capture commands allowed");}public void review(TrackingActivity owner){fail();}};TimeZone.setDefault(TimeZone.getTimeZone("Asia/Riyadh"));TonightScreen.clock=()->ZonedDateTime.of(2026,10,30,22,14,0,0,ZoneId.of("Asia/Riyadh")).toInstant().toEpochMilli();Appearance.save(c,false,0,0,false,false);Prefs.of(c).edit().putBoolean("noiseEnabled",false).commit();
            launch(MainActivity.class,new Intent(c,MainActivity.class).putExtra("visualReview",true));dial();Map<String,?> saved=new HashMap<>(plan.getAll());cancelledDrag();assertEquals("Pointer cancellation writes nothing",saved,plan.getAll());assertTrue(dial().getContentDescription().contains("8 h 30 min planned"));
            drag(420,450);assertEquals("Dragging never persists",saved,plan.getAll());capture("dial-draft");click("Cancel");dial();assertEquals(saved,plan.getAll());
            drag(1350,1320);assertTrue(dial().getContentDescription().contains("9 h planned"));recreate(PlanActivity.class);waitText("Adjust night");assertTrue("Pending interval survives recreation",dial().getContentDescription().contains("9 h planned"));capture("dial-review-restored");click("Use plan");assertTrue(d.wait(Until.gone(By.text("Adjust night")),5000));dial();assertEquals(1320,plan.getInt("bedtime",-1));assertEquals("Other handle remains independent",420,plan.getInt("wakeTime",-1));assertEquals(540,plan.getInt("goal",-1));assertEquals(1,schedules.get());capture("dial-saved");
            drag(420,450);SleepPlan changed=SleepPlans.load(c);changed.windDown=15;SleepPlans.save(c,changed);click("Use plan");waitText("Reload saved plan");assertEquals("Stale review cannot overwrite a newer plan",420,plan.getInt("wakeTime",-1));assertEquals(15,plan.getInt("windDownMinutes",-1));assertEquals(1,schedules.get());capture("dial-conflict");click("Cancel");dial();
            UiObject2 begin=d.wait(Until.findObject(By.desc("Begin night")),5000);assertNotNull(begin);begin.click();waitText("Settle in");assertNull(SleepSoundService.snapshot());capture("settle-in");UiObject2 timer=d.findObject(By.descStartsWith("Timer, "));assertNotNull(timer);timer.click();waitText("Sound timer");UiObject2 choice=d.findObject(By.desc("60 minutes"));assertNotNull(choice);choice.click();recreate(TrackingActivity.class);waitText("Sound timer");assertTrue(d.findObject(By.desc("60 minutes")).isChecked());capture("settle-timer");click("Cancel");waitText("Settle in");assertEquals(originalMix,mix.getAll());
            UiObject2 mic=d.findObject(By.desc("Record sounds"));if(mic==null){new UiScrollable(new UiSelector().scrollable(true)).scrollIntoView(new UiSelector().description("Record sounds"));mic=d.findObject(By.desc("Record sounds"));}assertNotNull(mic);mic.click();waitText("Use the microphone?");android.graphics.Rect previousAction=null;for(String label:List.of("Analyze & save clips","Analysis only","Cancel")){UiObject2 action=waitText(label);android.graphics.Rect bounds=action.getVisibleBounds();assertTrue("Consent actions retain full touch height",bounds.height()>=Design.dp(c,48));assertTrue("Consent actions use the available width",bounds.width()>=Design.dp(c,240));if(previousAction!=null)assertTrue("Consent actions never touch or overlap",bounds.top>previousAction.bottom);previousAction=bounds;}capture("settle-microphone-consent");click("Cancel");assertTrue("Consent sheet finishes before checking its parent",d.wait(Until.gone(By.text("Use the microphone?")),5000));UiObject2 restoredMic=d.wait(Until.findObject(By.desc("Record sounds")),5000);assertNotNull("Microphone switch returns after consent cancellation",restoredMic);assertFalse(restoredMic.isChecked());assertNull(SleepSoundService.snapshot());assertFalse(TrackingService.running);assertFalse(AlarmService.active);
            UiObject2 sensors=d.findObject(By.desc("Sensors & placement"));assertNotNull(sensors);sensors.click();waitText("Sensors & placement");capture("settle-sensors");d.pressBack();waitText("Settle in");assertEquals(originalMix,mix.getAll());
            d.pressBack();dial();try(Store store=new Store(c,database)){Alarm alarm=new Alarm(1);alarm.label="Daybreak";alarm.hour=7;alarm.minute=0;alarm.enabled=true;alarm.days.addAll(Set.of(1,2,3,4,5,6,7));store.save(alarm);}recreate(MainActivity.class);dial();drag(420,450);waitText("Use plan & review alarm");assertEquals(0,alarmSchedules.get());capture("dial-linked-review");click("Use plan & review alarm");waitText("Save alarm");try(Store store=new Store(c,database)){assertEquals("Plan save does not change alarm",0,store.alarm(1).minute);}assertEquals(450,plan.getInt("wakeTime",-1));assertEquals(0,alarmSchedules.get());assertNotNull(d.findObject(By.desc("Alarm time "+Design.clock(c,450))));recreate(AlarmEditorActivity.class);waitText("Save alarm");capture("dial-linked-alarm");click("Save alarm");assertTrue(d.wait(Until.gone(By.text("Save alarm")),5000));dial();try(Store store=new Store(c,database)){Alarm alarm=store.alarm(1);assertEquals(7,alarm.hour);assertEquals(30,alarm.minute);assertTrue(alarm.enabled);assertEquals(Set.of(1,2,3,4,5,6,7),alarm.days);assertEquals("Math",alarm.challenge);assertEquals(0,store.backup().getJSONArray("sessions").length());}assertEquals("Only explicit Save alarm schedules",1,alarmSchedules.get());

        }catch(Exception|AssertionError failure){try{File dir=new File(c.getExternalFilesDir(null),"verification");dir.mkdirs();d.takeScreenshot(new File(dir,"night-dial-interaction-failure.png"));d.dumpWindowHierarchy(new File(dir,"night-dial-interaction-failure.xml"));}catch(Exception ignored){}throw failure;}
        finally{
            i.runOnMainSync(()->owned.forEach(a->{if(!a.isDestroyed())a.finish();}));i.waitForIdleSync();long deadline=SystemClock.elapsedRealtime()+5000;while(owned.stream().anyMatch(a->!a.isDestroyed())&&SystemClock.elapsedRealtime()<deadline)SystemClock.sleep(50);for(Activity a:owned)if(a instanceof TrackingActivity t)t.awaitGraphReaders(10000);else if(a instanceof PlanActivity p)p.awaitReaders(10000);app.unregisterActivityLifecycleCallbacks(life);AlarmScheduling.port=alarmPort;Records.factory=records;SleepPlans.factory=plans;SleepPlans.reminders=reminders;SoundPreferences.factory=sounds;TrackingActivity.stores=stores;TrackingActivity.commands=commands;TonightScreen.clock=clock;TimeZone.setDefault(zone);
            SharedPreferences.Editor restore=Prefs.of(c).edit();for(String key:List.of(Appearance.AUTO,Appearance.THEME,Appearance.SIZE,Appearance.MOTION,Appearance.CONTRAST,"noiseEnabled","tracking","trackingPaused")){Object value=original.get(key);if(value instanceof Boolean)restore.putBoolean(key,(Boolean)value);else if(value instanceof Integer)restore.putInt(key,(Integer)value);else restore.remove(key);}assertTrue(restore.commit());assertEquals("No unrelated preferences changed",original,Prefs.of(c).getAll());if(owned.stream().allMatch(Activity::isDestroyed)){c.deleteDatabase(database);c.deleteSharedPreferences(name);c.deleteSharedPreferences(name+"-mix");}
        }
    }
}
